heses"}, {"id": "ea5940cd-0de7-482b-b1fe-61c8608f85fc", "type": "concept", "title": "Behavioral data"}, {"id": "2da6d83b-fd64-4955-bbf5-5a1714c90b61", "type": "concept", "title": "Research validity"}, {"id": "a37aeeb6-5420-447e-9ade-fe5bb1758f7d", "type": "concept", "title": "Ethical interpretation"}], "description": "Gist: The course begins with the habit of testing assumptions about consumers rather than relying on stereotypes."}]}, {"id": "876294b5-56df-4d62-b9f8-24e3f29efe6c", "type": "topic", "title": "Consumer Decision Process and Customer Journeys", "description": "Map how consumers move from need recognition through search, evaluation, choice, purchase, use, loyalty, advocacy, or churn.", "children": [{"id": "576ed332-17a8-408c-91f8-2c64fadda15a", "type": "subtopic", "title": "Decision stages", "children": [{"id": "7aaf0748-44de-48a0-91cb-41560e5f16d8", "type": "concept", "title": "Need recognition"}, {"id": "8854f3af-89ea-41fc-aaee-a05ffd1f1e37", "type": "concept", "title": "Search"}, {"id": "2393919b-394f-4e22-986e-8e852c1bb1cf", "type": "concept", "title": "Evaluation"}, {"id": "c570beb3-80d6-4f6d-af25-8ccf06103ba1", "type": "concept", "title": "Purchase and post-purchase"}], "description": "Gist: The classic decision process helps students organize what happens before, during, and after purchase."}, {"id": "098d7c5f-54cb-4e7e-84ae-a0edc45a7d33", "type": "subtopic", "title": "Journey mapping", "children": [{"id": "50d5213f-643e-411a-ae4a-23c7c9a6d2d6", "type": "concept", "title": "Awareness"}, {"id": "b05ebe4f-55ab-43aa-a616-78530dd3d921", "type": "concept", "title": "Consideration"}, {"id": "5bb5e87d-7f45-48d9-a99a-7de3aa6632ac", "type": "concept", "title": "Conversion"}, {"id": "bfbea213-8399-467f-809c-f84def7c8269", "type": "concept", "title": "Retention"}], "description": "Gist: Journeys reveal touchpoints, pain points, moments of truth, and opportunities for intervention."}, {"id": "611c6ebf-62a8-42bd-9b4c-21ceaf2ee6f6", "type": "subtopic", "title": "Low and high involvement", "children": [{"id": "f22bf4a4-e5e2-4b4d-9147-1050c0a19f7d", "type": "concept", "title": "Routine choice"}, {"id": "87d1c961-6295-4716-aac0-05f8fd82767c", "type": "concept", "title": "Complex choice"}, {"id": "a9fcc859-9a43-4d78-9d98-2a0e056bfe15", "type": "concept", "title": "Perceived risk"}, {"id": "8e51caa6-64c0-4a1c-bbfa-e5201007f8e3", "type": "concept", "title": "Impulse buying"}], "description": "Gist: Different decisions require different levels of attention, risk, search, and habit."}]}, {"id": "aaa8c4ec-b9e5-483e-b92b-b9e5d8e0b10d", "type": "topic", "title": "Motivation, Needs, Goals, and Jobs-to-be-Done", "description": "Analyze the goals, needs, tensions, habits, and practical jobs that make consumption meaningful.", "children": [{"id": "bbcc6a88-bb17-4158-9675-e12c0ff928ad", "type": "subtopic", "title": "Consumer needs", "children": [{"id": "11484b2e-877e-43e7-9da0-73debc18eae8", "type": "concept", "title": "Utilitarian value"}, {"id": "0e3531df-2865-4769-81f3-d98963be0a7c", "type": "concept", "title": "Hedonic value"}, {"id": "d3bf2453-10e6-4d08-ace1-3fd09a0e8a01", "type": "concept", "title": "Belonging"}, {"id": "0f0bf36e-8f36-44bc-9594-a8fe9b59d48b", "type": "concept", "title": "Status"}], "description": "Gist: Students examine functional, emotional, social, symbolic, and identity-based needs."}, {"id": "2f4f943b-927a-4617-b0ad-e1410cb559de", "type": "subtopic", "title": "Goals and conflict", "children": [{"id": "554dd077-b94b-402f-bbab-5a5e878f373c", "type": "concept", "title": "Approach-avoidance"}, {"id": "9c5c0448-d313-419d-8275-a30850f4d6a5", "type": "concept", "title": "Self-control"}, {"id": "48c70765-bb19-4296-bffc-4fde3d8aba78", "type": "concept", "title": "Convenience versus quality"}, {"id": "93fc5f89-b841-46bc-b209-cf4506f899af", "type": "concept", "title": "Short-term versus long-term goals"}], "description": "Gist: Consumer choice often involves competing goals and tradeoffs."}, {"id": "4c751e2b-5782-488d-99fd-0711cc3e0960", "type": "subtopic", "title": "Jobs-to-be-done", "children": [{"id": "a4fad417-82d0-4803-8d26-35195e260175", "type": "concept", "title": "Functional jobs"}, {"id": "5ba2f528-6b25-41fd-80f2-d2c896335760", "type": "concept", "title": "Emotional jobs"}, {"id": "66e2b690-b199-4ad4-add8-81a3550baa7a", "type": "concept", "title": "Social jobs"}, {"id": "9ed1000f-e11f-4730-a597-5f5e8b49a5e3", "type": "concept", "title": "Context of use"}], "description": "Gist: This lens helps students ask what progress a consumer is trying to make in a situation."}]}, {"id": "18ea43ae-2add-4d65-ba40-a6fc6078b53d", "type": "topic", "title": "Perception, Attention, and Sensory Marketing", "description": "Study how consumers notice, filter, interpret, and respond to stimuli across physical and digital environments.", "children": [{"id": "82652709-6ee1-42c1-a71d-64b50af05cc4", "type": "subtopic", "title": "Attention and salience", "children": [{"id": "c362aaac-512f-48e8-b8fb-a85031356083", "type": "concept", "title": "Selective attention"}, {"id": "fd85524e-0bf2-4b63-a7ad-a7468addff73", "type": "concept", "title": "Visual hierarchy"}, {"id": "3f6186ef-6ef8-4d68-9a73-9cf586e7a3fc", "type": "concept", "title": "Novelty"}, {"id": "d52cf642-0e0f-4e8e-91c8-3a756fbe23bd", "type": "concept", "title": "Clutter"}], "description": "Gist: Consumers cannot process everything, so marketers must understand what becomes noticeable and why."}, {"id": "692ae5ad-744a-4b5c-83a7-0663ccda271e", "type": "subtopic", "title": "Interpretation", "children": [{"id": "e712fb8a-c848-4dd1-9f87-805c40cc6dd7", "type": "concept", "title": "Schemas"}, {"id": "b0b6697c-aafe-4699-980d-6b165bc2b6af", "type": "concept", "title": "Priming"}, {"id": "fa220e8e-f93b-4a05-bf69-877a9ef45e53", "type": "concept", "title": "Ambiguity"}, {"id": "554b118d-5ffd-4199-83ee-76d8321430b3", "type": "concept", "title": "Context effects"}], "description": "Gist: Meaning depends on expectations, context, prior knowledge, culture, and framing."}, {"id": "f1c842e7-d9de-4fbf-9772-96e4ff2f4d50", "type": "subtopic", "title": "Sensory cues", "children": [{"id": "2332a06a-1df0-4564-a2a6-34063459b3d1", "type": "concept", "title": "Packaging"}, {"id": "dcfca72d-d6a8-4bbd-a1b5-b7986315373f", "type": "concept", "title": "Color"}, {"id": "abeedb82-8826-435a-90b6-117d5a779216", "type": "concept", "title": "Sound branding"}, {"id": "1a8a43e2-ef65-4964-8711-dbe1407ffe74", "type": "concept", "title": "Haptics"}], "description": "Gist: Sensory marketing shapes experience through sight, sound, touch, taste, smell, and interface feel."}]}, {"id": "85298664-f271-496f-901a-ab07e39a7876", "type": "topic", "title": "Learning, Memory, and Knowledge Structures", "description": "Understand how consumers learn from experience, advertising, reviews, repetition, and brand associations.", "children": [{"id": "75318cf8-23e6-4d51-96f6-892da66e62b9", "type": "subtopic", "title": "Learning processes", "children": [{"id": "a02d6058-d196-448b-adeb-d34d77929926", "type": "concept", "title": "Classical conditioning"}, {"id": "f6854c37-b64a-45e6-ae6e-76e073860aa7", "type": "concept", "title": "Operant conditioning"}, {"id": "133e80ad-fca9-4230-8084-77edb6c9c181", "type": "concept", "title": "Social learning"}, {"id": "9ebb5ff5-f374-4179-b464-ae016ec41a7a", "type": "concept", "title": "Habit formation"}], "description": "Gist: Consumers learn through experience, reinforcement, observation, and repeated exposure."}, {"id": "1f0906a9-6bb4-45bf-8574-cdf460dd8806", "type": "subtopic", "title": "Memory and retrieval", "children": [{"id": "9a9add29-fe42-4ff9-bc4f-13dbda4c365b", "type": "concept", "title": "Associative networks"}, {"id": "a5110b22-9e86-4f4f-a33f-0f56cd4b8785", "type": "concept", "title": "Recognition"}, {"id": "68012b8a-0141-458f-ab4b-aea5e3c2fa09", "type": "concept", "title": "Recall"}, {"id": "1f051383-9724-48f3-aae1-c7c47586154f", "type": "concept", "title": "Mental availability"}], "description": "Gist: Brand choice depends partly on what consumers remember and can retrieve at the right moment."}, {"id": "94ad53d1-5573-447c-adc5-27aff424b27f", "type": "subtopic", "title": "Brand associations", "children": [{"id": "c1a8a81c-bfda-4202-a53a-1fa70029d5bd", "type": "concept", "title": "Category cues"}, {"id": "eeac6ed9-af33-49c2-8188-82daefa34fe2", "type": "concept", "title": "Positioning links"}, {"id": "f240f2a2-ee28-40f4-81a2-a75ce0bb0c3b", "type": "concept", "title": "Usage occasions"}, {"id": "10dc8678-ef88-4da2-b5ce-c30153466793", "type": "concept", "title": "Distinctive assets"}], "description": "Gist: Knowledge structures shape category beliefs, consideration sets, and perceived fit."}]}, {"id": "c30dc90d-f728-458e-8679-faad6ae481fb", "type": "topic", "title": "Attitudes, Persuasion, and Influence", "description": "Explain how beliefs, feelings, norms, and persuasive messages shape preference and action.", "children": [{"id": "62ba2843-4132-4899-ad33-2fd3ea249b95", "type": "subtopic", "title": "Attitude formation", "children": [{"id": "b235502a-762b-46b8-a104-080ee15f7516", "type": "concept", "title": "Cognitive component"}, {"id": "c99b0257-4fca-4015-a0fd-3a56a54ef785", "type": "concept", "title": "Affective component"}, {"id": "509f96b7-c76d-47f1-99a1-32d874d8186f", "type": "concept", "title": "Behavioral component"}, {"id": "460f691c-1a48-4596-b0ab-3eafb5eebeee", "type": "concept", "title": "Ambivalence"}], "description": "Gist: Students learn how beliefs, affect, and behavioral intentions combine and sometimes conflict."}, {"id": "0e6d7a1b-3fdf-4a48-80fb-be2fec419d4e", "type": "subtopic", "title": "Persuasion pathways", "children": [{"id": "20d52637-914a-45e3-a5d3-3286b72505be", "type": "concept", "title": "Central route"}, {"id": "ea933452-9d76-4c9a-a76f-63efb9fbaeee", "type": "concept", "title": "Peripheral route"}, {"id": "9450b107-ef78-40d6-83b1-6957fb82d110", "type": "concept", "title": "Source credibility"}, {"id": "a811a7c0-7180-42e5-b072-2db2a5deb00e", "type": "concept", "title": "Message framing"}], "description": "Gist: Messages work differently depending on involvement, motivation, credibility, and route of processing."}, {"id": "9db545ba-6cd6-43ff-9864-c68439a792a7", "type": "subtopic", "title": "Influence principles", "children": [{"id": "187ea947-222b-4712-a2d2-c05181b3bcd4", "type": "concept", "title": "Reciprocity"}, {"id": "abaec091-09af-48ec-926d-819b505b0641", "type": "concept", "title": "Scarcity"}, {"id": "bda8b087-a1da-489b-a649-7302a2674454", "type": "concept", "title": "Authority"}, {"id": "40fe7237-c699-4bb4-ba81-4813a6aecbfa", "type": "concept", "title": "Consistency"}], "description": "Gist: Students connect persuasion to practical tactics and ethical boundaries."}]}, {"id": "fd97db3d-9cb0-495c-823a-4f6f1b27c745", "type": "topic", "title": "Emotion, Affect, and Experience Design", "description": "Examine how emotion, mood, arousal, delight, anxiety, and friction shape consumer experience and loyalty.", "children": [{"id": "a1fcbc91-6634-43a9-b7ba-78cb001fb4de", "type": "subtopic", "title": "Emotion in choice", "children": [{"id": "179904dd-dedf-4356-9ed9-50a18d23b460", "type": "concept", "title": "Anticipated emotion"}, {"id": "35c016ba-d45c-4300-8795-4188cbbee485", "type": "concept", "title": "Regret"}, {"id": "a6d4d27a-f8cd-46b9-bf70-b07bfc0712ff", "type": "concept", "title": "Delight"}, {"id": "0f9f24d8-7820-4c0e-8ec5-ff52034b40ac", "type": "concept", "title": "Anxiety"}], "description": "Gist: Emotion is not noise; it is often central to judgment, preference, memory, and loyalty."}, {"id": "4254d3b9-2b7f-4407-bb1b-9bc9684354d6", "type": "subtopic", "title": "Experience design", "children": [{"id": "b3b6192f-f688-4574-a926-e29f8fdefea0", "type": "concept", "title": "Pain points"}, {"id": "5194e0fc-7abf-4b47-812f-8e6f66db8ae5", "type": "concept", "title": "Peak-end rule"}, {"id": "c170a484-872e-430e-be27-9c10c713a775", "type": "concept", "title": "Service recovery"}, {"id": "8a4985e4-5f4e-4997-a4d3-c51cc1aa13aa", "type": "concept", "title": "Customer effort"}], "description": "Gist: Consumer experience depends on friction, flow, service moments, and emotional peaks."}, {"id": "3bcfd985-5033-458c-9bfc-b86c9fdbfedc", "type": "subtopic", "title": "Affect measurement", "children": [{"id": "cf226fd7-ec05-487b-a862-436eae1ef1f0", "type": "concept", "title": "Sentiment"}, {"id": "3ca8bb4d-02b2-45e0-8dd7-a0addccf27c5", "type": "concept", "title": "Reviews"}, {"id": "94439e66-c673-4e27-9744-81956a8e7874", "type": "concept", "title": "Experience surveys"}, {"id": "bcb7a2da-70de-4272-a4b0-32f6f7870c6c", "type": "concept", "title": "Behavioral signals"}], "description": "Gist: Students consider how firms can responsibly measure and improve emotional experience."}]}, {"id": "a84ea7c4-ee68-4c8c-addc-b570ea0bdb7c", "type": "topic", "title": "Identity, Self-Concept, Lifestyle, and Culture", "description": "Connect consumption to self-expression, social identity, lifestyle, values, culture, and meaning.", "children": [{"id": "f357b7f2-b8e2-4fa5-a4e0-3a43b779bfb6", "type": "subtopic", "title": "Consumption and self", "children": [{"id": "09535c38-a9ab-4bb9-8e87-26c6f285cb84", "type": "concept", "title": "Actual self"}, {"id": "dee4ab10-0111-4bbe-9e0e-9ab7f9b1bff7", "type": "concept", "title": "Ideal self"}, {"id": "b03da1ba-9b08-43af-bf2e-3504463c88bc", "type": "concept", "title": "Symbolic consumption"}, {"id": "36a07a75-1c2d-4bc0-8556-efe91edca7d1", "type": "concept", "title": "Identity signaling"}], "description": "Gist: People use products, brands, and experiences to express, explore, or protect identity."}, {"id": "5e25ca83-d9dc-456b-a310-94877198e444", "type": "subtopic", "title": "Lifestyle and values", "children": [{"id": "cc22c84b-29ad-4ac2-ae66-0ad0d70c1114", "type": "concept", "title": "Psychographics"}, {"id": "a6243575-acad-4964-b3eb-a948cbeb3c18", "type": "concept", "title": "VALS-style thinking"}, {"id": "f8383de5-4be5-45ae-8de8-8449e672ec4f", "type": "concept", "title": "Life stage"}, {"id": "3d168056-26e5-494d-8e05-f35f05731908", "type": "concept", "title": "Subcultures"}], "description": "Gist: Behavior patterns cluster around values, routines, tastes, and life situations."}, {"id": "e4b54017-f212-4f3b-a18a-0d8d7ab2c6b4", "type": "subtopic", "title": "Culture and meaning", "children": [{"id": "826012ae-c353-40f7-b90a-121cc4f17be8", "type": "concept", "title": "Cultural codes"}, {"id": "3523e716-56bb-4201-b500-3542a0d64fc5", "type": "concept", "title": "Rituals"}, {"id": "80b8d8ed-35f7-4ec3-bb19-2a810e23f476", "type": "concept", "title": "Norms"}, {"id": "120c2859-e33d-447a-840f-e49872970dbe", "type": "concept", "title": "Localization"}], "description": "Gist: Culture shapes categories, rituals, taboos, aspiration, status, and brand interpretation."}]}, {"id": "a5ddb26b-b72b-41a7-8789-10f538b2f28e", "type": "topic", "title": "Social Influence, Communities, Creators, and Word of Mouth", "description": "Study how consumers are influenced by peers, networks, communities, reviews, creators, and social proof.", "children": [{"id": "3ae8c77d-0815-4fac-af4c-072b454f5815", "type": "subtopic", "title": "Reference groups", "children": [{"id": "15abcbdd-63f3-4289-be5a-2a2a0ba0b93f", "type": "concept", "title": "Informational influence"}, {"id": "9997cc5d-d36c-4854-8aa2-668f850e1932", "type": "concept", "title": "Normative influence"}, {"id": "f0f7bcf5-4b76-4994-9ae5-c52a596219e2", "type": "concept", "title": "Aspirational groups"}, {"id": "0b301495-8205-4335-9b07-c8f2715d3968", "type": "concept", "title": "Dissociative groups"}], "description": "Gist: Consumers use others as sources of information, identity, comparison, and norm enforcement."}, {"id": "40a71205-5739-4ba9-b070-7b7ef06e5cfc", "type": "subtopic", "title": "Word of mouth", "children": [{"id": "f8280fd2-d06e-44bb-aa6a-bffb80f83823", "type": "concept", "title": "Reviews"}, {"id": "03fe35ac-3a26-436d-89dd-99d66f5dbe0f", "type": "concept", "title": "Referrals"}, {"id": "01711721-b231-4a6c-8350-5e8488b64660", "type": "concept", "title": "Virality"}, {"id": "667ed1ae-3bd4-4e58-a3b3-c44986443532", "type": "concept", "title": "Contagious content"}], "description": "Gist: Peer communication can be more trusted than brand communication."}, {"id": "fc00947b-fa30-4c2b-b8ef-6a0bfdd5c24c", "type": "subtopic", "title": "Creators and communities", "children": [{"id": "a3b4396f-b36c-4fe0-916f-7e9523fa0ffc", "type": "concept", "title": "Influencers"}, {"id": "9a8a6dee-9a14-4eeb-b2bc-c5b6209e2068", "type": "concept", "title": "Creator fit"}, {"id": "6d481855-797e-46ac-bf4c-ba44730174cb", "type": "concept", "title": "Community norms"}, {"id": "65a7ef3e-03e0-4cc3-a2d0-f86589394cc6", "type": "concept", "title": "User-generated content"}], "description": "Gist: Digital communities and creators shape discovery, trust, social proof, and belonging."}]}, {"id": "6deab5c3-675b-421b-95a0-09da7472d9ca", "type": "topic", "title": "Segmentation, Targeting, Positioning, and Personas", "description": "Translate behavioral insight into market structure, segment choice, positioning, and useful customer representations.", "children": [{"id": "c5f4a6fb-08c9-4534-9929-806a11926cd2", "type": "subtopic", "title": "Segmentation logic", "children": [{"id": "dd30c908-06a2-4255-8dc7-1d99a1d4c6a9", "type": "concept", "title": "Needs-based segments"}, {"id": "b16e6c90-406f-4f99-ba10-1921ccc8db44", "type": "concept", "title": "Behavioral segments"}, {"id": "25fa1baa-02fe-4409-9381-c1f2d9c3a924", "type": "concept", "title": "Occasion segments"}, {"id": "225fad64-76c4-4971-8968-276cec74e9db", "type": "concept", "title": "Value segments"}], "description": "Gist: Segments should reveal meaningful behavioral differences, not just demographic labels."}, {"id": "e0458ac0-ee82-4122-afa9-03455a4eecfb", "type": "subtopic", "title": "Targeting decisions", "children": [{"id": "f2c19db9-9f79-44f0-914e-c5aaedbc6a8c", "type": "concept", "title": "Segment size"}, {"id": "3cbdf850-b547-4add-8ffe-9e05bd8a3ef8", "type": "concept", "title": "Profitability"}, {"id": "e115e025-4cc9-4b74-9cfb-ac597d646365", "type": "concept", "title": "Accessibility"}, {"id": "ce4ba8bf-0295-49e8-b364-860d667cec14", "type": "concept", "title": "Strategic fit"}], "description": "Gist: Firms choose where to focus based on attractiveness, fit, economics, and ability to serve."}, {"id": "eed71b28-7e8e-41db-ae04-434acb94b66f", "type": "subtopic", "title": "Positioning and personas", "children": [{"id": "19820452-13db-4535-9e86-9fbea4c31d3b", "type": "concept", "title": "Value proposition"}, {"id": "ab5f77f6-bcec-4580-b7ee-617e5e33424c", "type": "concept", "title": "Perceptual map"}, {"id": "ea7849a2-0fe8-489a-9fcd-99e338545d14", "type": "concept", "title": "Persona risks"}, {"id": "97070089-0148-4e36-9d8a-2bc408643e06", "type": "concept", "title": "Messaging implications"}], "description": "Gist: Positioning and personas translate insight into decisions, but they must be evidence-based."}]}, {"id": "db001ae6-5ba0-4cdd-b5fc-c66b0f1c4527", "type": "topic", "title": "Brand Meaning, Brand Equity, and Loyalty", "description": "Explore how brands create memory, meaning, trust, differentiation, attachment, and measurable equity.", "children": [{"id": "ad0dce35-b82c-4367-b770-0d02b701400f", "type": "subtopic", "title": "Brand meaning", "children": [{"id": "82a07bdb-d9dd-46b8-95d5-60b9d5d0481c", "type": "concept", "title": "Associations"}, {"id": "98d01728-5406-4ff2-be2b-388eb4dff5e2", "type": "concept", "title": "Personality"}, {"id": "c7f3eb2f-7368-490f-8f25-0e75ac2b55ae", "type": "concept", "title": "Archetypes"}, {"id": "968c1594-df4e-4b2a-a1ef-a16bca5dd863", "type": "concept", "title": "Distinctive assets"}], "description": "Gist: Brands work as memory structures, symbolic resources, promises, and social signals."}, {"id": "083ace59-5175-48be-969e-63d9f603b6dd", "type": "subtopic", "title": "Brand equity", "children": [{"id": "f5c1a19a-4881-4e3d-94f4-e6b27a28bbf8", "type": "concept", "title": "Awareness"}, {"id": "917d989c-63c7-4234-b8e6-b85c00fb8985", "type": "concept", "title": "Preference"}, {"id": "fc3cc683-7ceb-436a-8be3-03be09513df2", "type": "concept", "title": "Premium"}, {"id": "12350817-8b16-4664-aaaa-e7a2ab1e7f4b", "type": "concept", "title": "Retention"}], "description": "Gist: Students connect brand strength to awareness, associations, perceived quality, loyalty, and financial value."}, {"id": "b1bcbb12-0620-402a-a6fb-f5beec2cafd4", "type": "subtopic", "title": "Loyalty and growth", "children": [{"id": "83c3a7fa-5634-4899-bfb1-c80a369f1005", "type": "concept", "title": "Repeat purchase"}, {"id": "e5d4fefe-31b7-412c-bc1d-cf38e1a98ac3", "type": "concept", "title": "Share of wallet"}, {"id": "c94efeb0-26ed-4b22-9107-d48b06f36cb0", "type": "concept", "title": "Mental availability"}, {"id": "10dd1e15-0de6-4dd7-8567-c2dc53c2eaab", "type": "concept", "title": "Customer lifetime value"}], "description": "Gist: The course compares loyalty, penetration, habit, switching, and customer equity perspectives."}]}, {"id": "87195e17-cce1-43d9-95fc-be2190aefc79", "type": "topic", "title": "Pricing, Value Perception, and Willingness to Pay", "description": "Analyze how consumers perceive price, value, fairness, discounts, subscriptions, and willingness to pay.", "children": [{"id": "9c86d96a-ac7a-433a-98e6-d3a37ac1f0fb", "type": "subtopic", "title": "Perceived value", "children": [{"id": "97d888a5-86b0-4e48-bbb3-3cdc360033a9", "type": "concept", "title": "Reference price"}, {"id": "f64c3c45-ae92-4394-ac5f-de4548f69011", "type": "concept", "title": "Value equation"}, {"id": "fd5c3b8d-1440-45b1-a8ed-f443eafeb658", "type": "concept", "title": "Fairness"}, {"id": "aaa60f25-259e-4827-a35e-9dc08190fd6d", "type": "concept", "title": "Tradeoffs"}], "description": "Gist: Consumers evaluate price relative to benefits, alternatives, reference points, and fairness."}, {"id": "20ad0084-8f07-4c40-b8d5-ac33cd3e9a20", "type": "subtopic", "title": "Behavioral pricing", "children": [{"id": "407e1d30-be5d-4cc1-8a67-418b2f035892", "type": "concept", "title": "Anchoring"}, {"id": "d03af0b3-dafd-4700-b3a0-a07a826a10c5", "type": "concept", "title": "Decoy effects"}, {"id": "eaa51319-fa54-4d37-821b-abd6b2dafb00", "type": "concept", "title": "Partitioned pricing"}, {"id": "e5f1c392-8eae-4702-8979-44da2f016f8c", "type": "concept", "title": "Discount framing"}], "description": "Gist: Pricing effects often depend on framing and psychology, not only objective cost."}, {"id": "357d47e6-dcdc-4652-891e-aeb9644c435c", "type": "subtopic", "title": "Value capture", "children": [{"id": "fd5b6496-e7de-49e0-98a7-004d69bf7c66", "type": "concept", "title": "Price sensitivity"}, {"id": "3fe04363-871c-4edc-9eec-4758c7e5a9b5", "type": "concept", "title": "Subscriptions"}, {"id": "ea0da32f-86e1-4946-9162-339cc12c186d", "type": "concept", "title": "Bundles"}, {"id": "f831fdba-a6d7-4060-b619-9a0494656f62", "type": "concept", "title": "Promotions"}], "description": "Gist: Students connect willingness to pay to segmentation, product design, and pricing strategy."}]}, {"id": "70c92093-c02f-488f-8b45-241d86749f2f", "type": "topic", "title": "Choice Architecture, Nudges, and Decision Biases", "description": "Use behavioral economics to understand heuristics, biases, defaults, framing, and ethical choice design.", "children": [{"id": "6eb25b22-06f8-47a2-9cc4-e4f0218bf037", "type": "subtopic", "title": "Heuristics and biases", "children": [{"id": "7bf722d1-bae3-41eb-aa75-9e66a77dbea3", "type": "concept", "title": "Availability"}, {"id": "01df9cbf-7559-4d78-8c2f-caff733287c3", "type": "concept", "title": "Representativeness"}, {"id": "6b1316f1-b3e3-4785-9292-16ffda00ea96", "type": "concept", "title": "Loss aversion"}, {"id": "86d51e14-0193-42cc-b60c-ecac22db3e79", "type": "concept", "title": "Status quo bias"}], "description": "Gist: Consumers simplify decisions in ways that can be predictable and consequential."}, {"id": "6b899b25-fba0-4a76-a8d7-4bbe106a1457", "type": "subtopic", "title": "Choice architecture", "children": [{"id": "af0fdbc1-e1b5-4bcf-bb29-8883c2f5293b", "type": "concept", "title": "Defaults"}, {"id": "e0bc553d-c54f-4ed3-bc71-3af402337ac7", "type": "concept", "title": "Choice overload"}, {"id": "0d880b80-76da-4899-b704-577eea56c66b", "type": "concept", "title": "Framing"}, {"id": "b57788c7-f701-4388-bc0a-443281a4f88c", "type": "concept", "title": "Friction design"}], "description": "Gist: The design of options shapes decisions through defaults, ordering, friction, and salience."}, {"id": "b1ce6d54-c077-46a4-a166-9a1790c0a247", "type": "subtopic", "title": "Ethics of nudging", "children": [{"id": "b2a93e3f-bf84-4855-8f73-28daba68585b", "type": "concept", "title": "Transparency"}, {"id": "888f80db-842f-4d3e-89d7-c016ac351c1f", "type": "concept", "title": "Consumer welfare"}, {"id": "3add4c65-ea00-498b-99f0-b985a68bd57f", "type": "concept", "title": "Dark patterns"}, {"id": "7bd9f1ba-22e9-4522-b3f4-5b9c84939a44", "type": "concept", "title": "Autonomy"}], "description": "Gist: Students learn to distinguish helpful choice design from manipulation."}]}, {"id": "933b6b8a-9cbe-4fd4-9693-5c559819c718", "type": "topic", "title": "Consumer Research Methods and Experiments", "description": "Build skills in qualitative, quantitative, observational, survey, experimental, and ethnographic consumer research.", "children": [{"id": "e5fd87b9-6104-4de4-90ea-b872da6a7a8d", "type": "subtopic", "title": "Qualitative methods", "children": [{"id": "d44ea0e0-f022-4787-ace4-4f2e2f00ce0c", "type": "concept", "title": "Interviews"}, {"id": "7d373848-53b8-497d-a966-a8a6255b0ca4", "type": "concept", "title": "Focus groups"}, {"id": "3a960d06-0d49-4c0a-8d22-1520f2e424d4", "type": "concept", "title": "Ethnography"}, {"id": "7e701b3f-f724-4cee-aff8-dda9a8623908", "type": "concept", "title": "Diary studies"}], "description": "Gist: Qualitative research helps uncover meaning, language, motivations, and context."}, {"id": "360e1a01-1e22-4be4-8160-c68fd7d2368d", "type": "subtopic", "title": "Quantitative methods", "children": [{"id": "258111b9-3e76-498a-942e-d00c33447121", "type": "concept", "title": "Surveys"}, {"id": "3744a647-4698-4761-9e33-85d302addd8c", "type": "concept", "title": "Conjoint basics"}, {"id": "33ad994b-718e-4214-9a39-35baeadfb778", "type": "concept", "title": "Choice modeling"}, {"id": "0db29369-5b37-432e-a5df-c75e64e018bd", "type": "concept", "title": "Sampling"}], "description": "Gist: Quantitative tools measure preferences, segments, attitudes, and behavioral patterns."}, {"id": "18511d41-240a-48c0-920c-c14c0081497c", "type": "subtopic", "title": "Experiments and causality", "children": [{"id": "1d0a027a-d1c0-445c-8eec-14fa0e598dfb", "type": "concept", "title": "A/B tests"}, {"id": "14cc4728-7a29-4518-bb0a-e1595023ff85", "type": "concept", "title": "Randomization"}, {"id": "0dbe8de7-1928-4e86-ba9f-a08cf75edf6a", "type": "concept", "title": "Control groups"}, {"id": "d744ddc2-d2f3-4a04-8eef-5616d437ca93", "type": "concept", "title": "Validity"}], "description": "Gist: Students learn how experiments test what actually changes behavior."}]}, {"id": "acea5252-4b2c-4c3d-b263-4bf25855f4f8", "type": "topic", "title": "Digital Consumer Behavior, Data, Privacy, and Analytics", "description": "Study consumer behavior in digital journeys through analytics, attribution, personalization, privacy, consent, and experimentation.", "children": [{"id": "d31cf7f0-3019-4743-8f21-59680e09ce71", "type": "subtopic", "title": "Digital journeys", "children": [{"id": "95c9fecb-48a4-4395-95e6-d7447ba8eb0c", "type": "concept", "title": "Intent capture"}, {"id": "84bcf971-41fb-40c6-a623-96da3684186a", "type": "concept", "title": "Funnel analytics"}, {"id": "b1a05159-8651-4b97-bf65-9b6f3f45d83c", "type": "concept", "title": "Omnichannel journeys"}, {"id": "a6bf05b3-d71a-4d03-a2b6-33ca1bba8d2e", "type": "concept", "title": "Retargeting"}], "description": "Gist: Digital behavior leaves signals across search, social, email, web, apps, commerce, and CRM."}, {"id": "3dddc2cc-be9b-4b3e-8a89-3fe0b6d7fd66", "type": "subtopic", "title": "Measurement and attribution", "children": [{"id": "6fd260f2-c009-4d87-b8e5-9f788b0aa073", "type": "concept", "title": "Conversion"}, {"id": "8ac0510c-ccbc-4a69-a92b-54d5056a002a", "type": "concept", "title": "Incrementality"}, {"id": "02e48f7c-cec1-45ef-a32e-6d2f4255fb41", "type": "concept", "title": "Marketing mix modeling"}, {"id": "d895e7e3-77fe-4811-ae71-3423eeeb809c", "type": "concept", "title": "Customer journey analytics"}], "description": "Gist: Students connect behavior to metrics while recognizing attribution limits."}, {"id": "3719e5b4-0c9b-4e45-8787-fdf988bdb884", "type": "subtopic", "title": "Privacy and consent", "children": [{"id": "d5635ca7-7f5b-4082-8215-f243f27db021", "type": "concept", "title": "First-party data"}, {"id": "c2ac5a46-13fc-4dca-b61e-0b1d85d39587", "type": "concept", "title": "Cookie changes"}, {"id": "0ee62bee-3402-4399-8d8c-bef133952157", "type": "concept", "title": "Consent management"}, {"id": "50f86a97-c9e0-4619-a105-a7085e35bf43", "type": "concept", "title": "Algorithmic fairness"}], "description": "Gist: Responsible consumer insight requires data ethics, consent, security, and respect for boundaries."}]}, {"id": "80d98dce-767e-4562-bbb3-85bc5a70aa2f", "type": "topic", "title": "Applied Consumer Insight Project", "description": "Synthesize behavioral theory, research evidence, segmentation, journey analysis, and ethical recommendations in a final project.", "children": [{"id": "b65546a8-721c-4d40-aa95-f4ee71aaf5fa", "type": "subtopic", "title": "Problem framing", "children": [{"id": "0405d642-5da2-400d-a264-04006224fc6f", "type": "concept", "title": "Business objective"}, {"id": "832e75ff-f63c-4ba9-8284-91146ad279ac", "type": "concept", "title": "Consumer question"}, {"id": "d1717581-2399-4afb-a48d-0372243a2939", "type": "concept", "title": "Hypothesis"}, {"id": "1054dfbb-eed2-4e17-9ed5-30adcab14257", "type": "concept", "title": "Decision use"}], "description": "Gist: Students turn a marketing problem into a consumer insight question that can be researched."}, {"id": "d3cf9b71-e438-4815-950a-e83c4e7e2871", "type": "subtopic", "title": "Evidence synthesis", "children": [{"id": "2f0c9dfd-80dd-485c-959b-2f00d37af8f1", "type": "concept", "title": "Primary research"}, {"id": "cb5339a2-db17-4642-b1cd-c90752d2a3e6", "type": "concept", "title": "Secondary evidence"}, {"id": "39a71e4e-ad61-4b28-bf5b-930591e7720b", "type": "concept", "title": "Journey map"}, {"id": "e514d478-ea85-4846-bdc1-663161e9b1a0", "type": "concept", "title": "Persona or segment"}], "description": "Gist: The project combines theory, data, research, and market context into an actionable insight."}, {"id": "ec793a9f-771f-4b25-9bc2-7537ec3ce665", "type": "subtopic", "title": "Recommendation and ethics", "children": [{"id": "e8de6dfd-fd56-4041-b7af-caba64e59ced", "type": "concept", "title": "Strategic recommendation"}, {"id": "09994fe3-1695-42e7-acdd-1e98a44691fe", "type": "concept", "title": "Experiment plan"}, {"id": "df2f52bb-8edb-4238-92a2-cc20a0555585", "type": "concept", "title": "Metrics"}, {"id": "0371e615-4835-42ae-abdc-6fa02ff226f3", "type": "concept", "title": "Consumer welfare"}], "description": "Gist: Students translate insight into a responsible marketing recommendation."}]}], "dbBacked": true}$cbehjson$::jsonb,
